local Control=require(script.Parent.Parent.Base.Control)
return function(ctx,default,callback) local f=Instance.new("Frame",ctx.Parent);f.Name="Vector3Input";f.Size=UDim2.new(1,0,0,38);f.BackgroundTransparency=1;local c=Control.new(f,ctx,default or Vector3.zero);local fields={"X","Y","Z"};for i,k in ipairs(fields)do local b=Instance.new("TextBox",f);b.Position=UDim2.new((i-1)/3,2,0,0);b.Size=UDim2.new(1/3,-4,1,0);b.BackgroundColor3=ctx.Theme:Get("SurfaceAlt");b.TextColor3=ctx.Theme:Get("Text");b.Text=tostring(c.Value[k]);b.Font=Enum.Font.Gotham;b.TextSize=12;Instance.new("UICorner",b).CornerRadius=UDim.new(0,8);ctx.Maid:Give(b.FocusLost:Connect(function()local v={X=tonumber(b.Text) or c.Value.X,Y=c.Value.Y,Z=c.Value.Z};v[k]=tonumber(b.Text) or c.Value[k];c:SetValue(Vector3.new(v.X,v.Y,v.Z));if callback then callback(c.Value)end end))end;return c end
